-- 0054: same-primary/new-tenant retained-source erasure bridges, not external disposal.
-- Drain every pre-0054 writer and transaction; migration does not backfill or activate.
-- NULL protocol is genuine historical evidence, never permission to downgrade a v1 proof.
-- These nine tables retain opaque digests only. They must not store source body, raw
-- session/turn/item/usage IDs, locator, credential, or externally supplied authority.
-- Entries precede destructive DELETE; final receipts follow the actual old ACK/terminal.
-- Do not add a sixth value to published 0040/0041 CHECKs or invent a v1 binding for v2.

ALTER TABLE tenant_erasure_admissions ADD COLUMN telemetry_retained_source_protocol
  VARCHAR(64) COLLATE utf8mb4_0900_as_cs NULL DEFAULT NULL,
  ADD CONSTRAINT chk_tt_retained_admission_protocol CHECK
    (telemetry_retained_source_protocol IS NULL OR BINARY telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1');
ALTER TABLE tenant_purge_plan_jobs ADD COLUMN telemetry_retained_source_protocol
  VARCHAR(64) COLLATE utf8mb4_0900_as_cs NULL DEFAULT NULL,
  ADD CONSTRAINT chk_tt_retained_plan_protocol CHECK
    (telemetry_retained_source_protocol IS NULL OR BINARY telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1');

CREATE TABLE IF NOT EXISTS tenant_telemetry_retained_source_t1_entries (
  scope VARCHAR(72) COLLATE utf8mb4_0900_as_cs NOT NULL,
  request_id VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_generation BIGINT UNSIGNED NOT NULL,
  t1_profile_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  t1_fence_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  source_identity_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  state VARCHAR(32) COLLATE utf8mb4_0900_as_cs NOT NULL,
  write_operation_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  failure_commit_receipt_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  source_binding_receipt_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  membership_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  write_job_evidence_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  reservation_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  write_ack_receipt_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  inventory_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  inventory_receipt_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  payload_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NULL,
  source_high_water_db_ms BIGINT UNSIGNED NOT NULL,
  captured_at_db_ms BIGINT UNSIGNED NOT NULL,
  receipt_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  receipt_json JSON NOT NULL,
  PRIMARY KEY (request_id,source_identity_sha256),
  UNIQUE KEY uk_tt_retained_t1entries_receipt (receipt_sha256),
  KEY idx_tt_retained_t1entries_tenant (tenant_id,request_id),
  CONSTRAINT fk_tt_retained_t1entries_admission FOREIGN KEY (request_id)
    REFERENCES tenant_erasure_admissions(request_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_tt_retained_t1entries_shape CHECK (
    scope='tenant-telemetry-retained-source-t1-entry-v1'
    AND subject_generation>0 AND CHAR_LENGTH(tenant_id) BETWEEN 1 AND 128
    AND JSON_TYPE(receipt_json)='OBJECT'
    AND state IN ('written_ack','pending','reserved','blocked','unknown')
    AND t1_profile_sha256 REGEXP '^[0-9a-f]{64}$'
    AND t1_fence_sha256 REGEXP '^[0-9a-f]{64}$'
    AND source_identity_sha256 REGEXP '^[0-9a-f]{64}$'
    AND (write_operation_sha256 IS NULL OR write_operation_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (failure_commit_receipt_sha256 IS NULL OR failure_commit_receipt_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (source_binding_receipt_sha256 IS NULL OR source_binding_receipt_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (membership_sha256 IS NULL OR membership_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (write_job_evidence_sha256 IS NULL OR write_job_evidence_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (reservation_sha256 IS NULL OR reservation_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (write_ack_receipt_sha256 IS NULL OR write_ack_receipt_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (inventory_sha256 IS NULL OR inventory_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (inventory_receipt_sha256 IS NULL OR inventory_receipt_sha256 REGEXP '^[0-9a-f]{64}$')
    AND (payload_sha256 IS NULL OR payload_sha256 REGEXP '^[0-9a-f]{64}$')
    AND receipt_sha256 REGEXP '^[0-9a-f]{64}$'
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

SELECT scope,request_id,tenant_id,subject_generation,t1_profile_sha256,t1_fence_sha256,source_identity_sha256,state,write_operation_sha256,failure_commit_receipt_sha256,source_binding_receipt_sha256,membership_sha256,write_job_evidence_sha256,reservation_sha256,write_ack_receipt_sha256,inventory_sha256,inventory_receipt_sha256,payload_sha256,source_high_water_db_ms,captured_at_db_ms,receipt_sha256,receipt_json FROM tenant_telemetry_retained_source_t1_entries
  FORCE INDEX (PRIMARY,uk_tt_retained_t1entries_receipt,idx_tt_retained_t1entries_tenant) WHERE 1=0;

