    AND blocked_root_sha256 REGEXP '^[0-9a-f]{64}$'
    AND unknown_root_sha256 REGEXP '^[0-9a-f]{64}$'
    AND receipt_sha256 REGEXP '^[0-9a-f]{64}$'
