  receipt_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  receipt_json JSON NOT NULL,
  PRIMARY KEY (request_id),
  UNIQUE KEY uk_tt_retained_canonicalreceipts_receipt (receipt_sha256),
  KEY idx_tt_retained_canonicalreceipts_tenant (tenant_id,request_id),
  CONSTRAINT fk_tt_retained_canonicalreceipts_admission FOREIGN KEY (request_id)
    REFERENCES tenant_erasure_admissions(request_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_tt_retained_canonicalreceipts_shape CHECK (
    scope='tenant-telemetry-retained-source-canonical-receipt-v1'
    AND subject_generation>0 AND CHAR_LENGTH(tenant_id) BETWEEN 1 AND 128
    AND JSON_TYPE(receipt_json)='OBJECT'
    AND plan_build_generation>0 AND execution_generation>0 AND database_purge_generation>0 AND completed_claim_attempt>0
    AND t1_profile_sha256 REGEXP '^[0-9a-f]{64}$'
    AND t1_fence_sha256 REGEXP '^[0-9a-f]{64}$'
    AND cohort_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND catalog_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND usage_release_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND plan_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND local_physical_ack_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND predelete_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND t3f_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND owner_closure_receipt_sha256 REGEXP '^[0-9a-f]{64}$'
    AND grave_marker_root_sha256 REGEXP '^[0-9a-f]{64}$'
    AND entry_root_sha256 REGEXP '^[0-9a-f]{64}$'
    AND completed_claim_token_sha256 REGEXP '^[0-9a-f]{64}$'
    AND receipt_sha256 REGEXP '^[0-9a-f]{64}$'
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

SELECT scope,request_id,tenant_id,subject_generation,t1_profile_sha256,t1_fence_sha256,plan_build_generation,execution_generation,database_purge_generation,cohort_receipt_sha256,catalog_receipt_sha256,usage_release_receipt_sha256,plan_receipt_sha256,local_physical_ack_receipt_sha256,predelete_receipt_sha256,t3f_receipt_sha256,owner_closure_receipt_sha256,grave_marker_root_sha256,entry_count,entry_root_sha256,source_high_water_db_ms,store_db_timestamp_ms,completed_claim_attempt,completed_claim_token_sha256,receipt_sha256,receipt_json FROM tenant_telemetry_retained_source_canonical_receipts
  FORCE INDEX (PRIMARY,uk_tt_retained_canonicalreceipts_receipt,idx_tt_retained_canonicalreceipts_tenant) WHERE 1=0;
-- JSON projections are byte-exact; missing and JSON null are distinct.
-- Cryptographic roots/HMACs are independently rebuilt by the trusted store/startup audit.

DROP TRIGGER IF EXISTS trg_tt_retained_t1_entries_json_bi;
CREATE TRIGGER trg_tt_retained_t1_entries_json_bi BEFORE INSERT ON tenant_telemetry_retained_source_t1_entries FOR EACH ROW BEGIN IF ( JSON_TYPE(NEW.receipt_json)='OBJECT' AND JSON_LENGTH(NEW.receipt_json)=21 AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.scope'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.scope'))=BINARY NEW.scope) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.requestId'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.requestId'))=BINARY NEW.request_id) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.tenantId'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.tenantId'))=BINARY NEW.tenant_id) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.subjectGeneration')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.subjectGeneration')) AS UNSIGNED)=NEW.subject_generation AND NEW.subject_generation<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.t1ProfileSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.t1ProfileSha256'))=BINARY NEW.t1_profile_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.t1FenceSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.t1FenceSha256'))=BINARY NEW.t1_fence_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.sourceIdentitySha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.sourceIdentitySha256'))=BINARY NEW.source_identity_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.state'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.state'))=BINARY NEW.state) AND ((NEW.write_operation_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.writeOperationSha256'))='NULL') OR (NEW.write_operation_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.writeOperationSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.writeOperationSha256'))=BINARY NEW.write_operation_sha256)) AND ((NEW.failure_commit_receipt_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.failureCommitReceiptSha256'))='NULL') OR (NEW.failure_commit_receipt_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.failureCommitReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.failureCommitReceiptSha256'))=BINARY NEW.failure_commit_receipt_sha256)) AND ((NEW.source_binding_receipt_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.sourceBindingReceiptSha256'))='NULL') OR (NEW.source_binding_receipt_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.sourceBindingReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.sourceBindingReceiptSha256'))=BINARY NEW.source_binding_receipt_sha256)) AND ((NEW.membership_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.membershipSha256'))='NULL') OR (NEW.membership_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.membershipSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.membershipSha256'))=BINARY NEW.membership_sha256)) AND ((NEW.write_job_evidence_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.writeJobEvidenceSha256'))='NULL') OR (NEW.write_job_evidence_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.writeJobEvidenceSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.writeJobEvidenceSha256'))=BINARY NEW.write_job_evidence_sha256)) AND ((NEW.reservation_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.reservationSha256'))='NULL') OR (NEW.reservation_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.reservationSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.reservationSha256'))=BINARY NEW.reservation_sha256)) AND ((NEW.write_ack_receipt_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.writeAckReceiptSha256'))='NULL') OR (NEW.write_ack_receipt_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.writeAckReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.writeAckReceiptSha256'))=BINARY NEW.write_ack_receipt_sha256)) AND ((NEW.inventory_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.inventorySha256'))='NULL') OR (NEW.inventory_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.inventorySha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.inventorySha256'))=BINARY NEW.inventory_sha256)) AND ((NEW.inventory_receipt_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.inventoryReceiptSha256'))='NULL') OR (NEW.inventory_receipt_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.inventoryReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.inventoryReceiptSha256'))=BINARY NEW.inventory_receipt_sha256)) AND ((NEW.payload_sha256 IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.payloadSha256'))='NULL') OR (NEW.payload_sha256 IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.payloadSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.payloadSha256'))=BINARY NEW.payload_sha256)) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.sourceHighWaterDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.sourceHighWaterDbMs')) AS UNSIGNED)=NEW.source_high_water_db_ms AND NEW.source_high_water_db_ms<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.capturedAtDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.capturedAtDbMs')) AS UNSIGNED)=NEW.captured_at_db_ms AND NEW.captured_at_db_ms<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.receiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.receiptSha256'))=BINARY NEW.receipt_sha256) AND BINARY NEW.receipt_sha256=BINARY SHA2(CONCAT(NEW.scope,CHAR(0),CONCAT('{','"capturedAtDbMs":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.capturedAtDbMs') AS CHAR),',"failureCommitReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.failureCommitReceiptSha256') AS CHAR),',"inventoryReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.inventoryReceiptSha256') AS CHAR),',"inventorySha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.inventorySha256') AS CHAR),',"membershipSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.membershipSha256') AS CHAR),',"payloadSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.payloadSha256') AS CHAR),',"requestId":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.requestId') AS CHAR),',"reservationSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.reservationSha256') AS CHAR),',"scope":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.scope') AS CHAR),',"sourceBindingReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.sourceBindingReceiptSha256') AS CHAR),',"sourceHighWaterDbMs":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.sourceHighWaterDbMs') AS CHAR),',"sourceIdentitySha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.sourceIdentitySha256') AS CHAR),',"state":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.state') AS CHAR),',"subjectGeneration":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.subjectGeneration') AS CHAR),',"t1FenceSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.t1FenceSha256') AS CHAR),',"t1ProfileSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.t1ProfileSha256') AS CHAR),',"tenantId":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.tenantId') AS CHAR),',"writeAckReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.writeAckReceiptSha256') AS CHAR),',"writeJobEvidenceSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.writeJobEvidenceSha256') AS CHAR),',"writeOperationSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.writeOperationSha256') AS CHAR),'}')),256) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source JSON projection is invalid'; END IF; END;
DROP TRIGGER IF EXISTS trg_tt_retained_t1_entries_bu;
CREATE TRIGGER trg_tt_retained_t1_entries_bu BEFORE UPDATE ON tenant_telemetry_retained_source_t1_entries FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source evidence is immutable';
DROP TRIGGER IF EXISTS trg_tt_retained_t1_entries_bd;
CREATE TRIGGER trg_tt_retained_t1_entries_bd BEFORE DELETE ON tenant_telemetry_retained_source_t1_entries FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source evidence is append-only';

DROP TRIGGER IF EXISTS trg_tt_retained_t1_receipts_json_bi;
CREATE TRIGGER trg_tt_retained_t1_receipts_json_bi BEFORE INSERT ON tenant_telemetry_retained_source_t1_receipts FOR EACH ROW BEGIN IF ( JSON_TYPE(NEW.receipt_json)='OBJECT' AND JSON_LENGTH(NEW.receipt_json)=29 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile'))='OBJECT' AND ((BINARY NEW.profile_kind=BINARY 'eligible-primary' AND JSON_LENGTH(JSON_EXTRACT(NEW.receipt_json,'$.profile'))=4 AND JSON_CONTAINS_PATH(NEW.receipt_json,'all','$.profile.kind','$.profile.primaryBinding','$.profile.legacyFailedItemCount','$.profile.legacyFailedItemRootSha256')=1 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.legacyFailedItemCount')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.legacyFailedItemCount')=0 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.legacyFailedItemRootSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.legacyFailedItemRootSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding'))='OBJECT' AND JSON_LENGTH(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding'))=20 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.scope'))=BINARY 'tenant-telemetry-retained-source-primary-v1' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleHistoryStatus'))=BINARY 'complete_since_creation' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureStatus'))=BINARY 'capture_since_tenant_creation' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureControlEvidenceSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureControlEvidenceSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleControlEvidenceSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleControlEvidenceSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.refKeyIdSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.refKeyIdSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.logsTargetSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.logsTargetSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.logsTargetReceiptSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.logsTargetReceiptSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeBindingSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeBindingSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeControlEvidenceSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeControlEvidenceSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleCoverageEvidenceSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleCoverageEvidenceSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureCoverageEvidenceSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureCoverageEvidenceSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.evidenceSha256'))='STRING' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.evidenceSha256')) REGEXP '^[0-9a-f]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeControlGeneration')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.runtimeControlGeneration') BETWEEN 1 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleActivatedAtDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleActivatedAtDbMs') BETWEEN 0 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureActivatedAtDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureActivatedAtDbMs') BETWEEN 0 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleCoverageStartedAtDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.lifecycleCoverageStartedAtDbMs') BETWEEN 0 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureCoverageStartedAtDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.captureCoverageStartedAtDbMs') BETWEEN 0 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.tenantCreatedAtDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.receipt_json,'$.profile.primaryBinding.tenantCreatedAtDbMs') BETWEEN 0 AND 9007199254740991 AND JSON_CONTAINS_PATH(NEW.receipt_json,'all','$.profile.primaryBinding.scope','$.profile.primaryBinding.captureControlEvidenceSha256','$.profile.primaryBinding.lifecycleControlEvidenceSha256','$.profile.primaryBinding.refKeyIdSha256','$.profile.primaryBinding.logsTargetSha256','$.profile.primaryBinding.logsTargetReceiptSha256','$.profile.primaryBinding.runtimeEpochSha256','$.profile.primaryBinding.runtimeBindingSha256','$.profile.pri