CREATE TRIGGER trg_tt_retained_canonical_receipts_json_bi BEFORE INSERT ON tenant_telemetry_retained_source_canonical_receipts FOR EACH ROW BEGIN IF ( JSON_TYPE(NEW.receipt_json)='OBJECT' AND JSON_LENGTH(NEW.receipt_json)=29 AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.scope'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.scope'))=BINARY NEW.scope) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.requestId'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.requestId'))=BINARY NEW.request_id) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.tenantId'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.tenantId'))=BINARY NEW.tenant_id) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.subjectGeneration')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.subjectGeneration')) AS UNSIGNED)=NEW.subject_generation AND NEW.subject_generation<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.t1ProfileSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.t1ProfileSha256'))=BINARY NEW.t1_profile_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.t1FenceSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.t1FenceSha256'))=BINARY NEW.t1_fence_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.planBuildGeneration')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.planBuildGeneration')) AS UNSIGNED)=NEW.plan_build_generation AND NEW.plan_build_generation<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.executionGeneration')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.executionGeneration')) AS UNSIGNED)=NEW.execution_generation AND NEW.execution_generation<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.databasePurgeGeneration')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.databasePurgeGeneration')) AS UNSIGNED)=NEW.database_purge_generation AND NEW.database_purge_generation<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.cohortReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.cohortReceiptSha256'))=BINARY NEW.cohort_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.catalogReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.catalogReceiptSha256'))=BINARY NEW.catalog_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.usageReleaseReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.usageReleaseReceiptSha256'))=BINARY NEW.usage_release_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.planReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.planReceiptSha256'))=BINARY NEW.plan_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.localPhysicalAckReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.localPhysicalAckReceiptSha256'))=BINARY NEW.local_physical_ack_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.preDeleteReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.preDeleteReceiptSha256'))=BINARY NEW.predelete_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.t3fReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.t3fReceiptSha256'))=BINARY NEW.t3f_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.ownerClosureReceiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.ownerClosureReceiptSha256'))=BINARY NEW.owner_closure_receipt_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.graveMarkerRootSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.graveMarkerRootSha256'))=BINARY NEW.grave_marker_root_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.entryCount')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.entryCount')) AS UNSIGNED)=NEW.entry_count AND NEW.entry_count<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.entryRootSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.entryRootSha256'))=BINARY NEW.entry_root_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.sourceHighWaterDbMs')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.sourceHighWaterDbMs')) AS UNSIGNED)=NEW.source_high_water_db_ms AND NEW.source_high_water_db_ms<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.storeDbTimestampMs')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.storeDbTimestampMs')) AS UNSIGNED)=NEW.store_db_timestamp_ms AND NEW.store_db_timestamp_ms<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.completedClaimAttempt')) IN ('INTEGER','UNSIGNED INTEGER') AND CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.completedClaimAttempt')) AS UNSIGNED)=NEW.completed_claim_attempt AND NEW.completed_claim_attempt<=9007199254740991) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.completedClaimTokenSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.completedClaimTokenSha256'))=BINARY NEW.completed_claim_token_sha256) AND (JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.receiptSha256'))='STRING' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.receipt_json,'$.receiptSha256'))=BINARY NEW.receipt_sha256) AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.executionReady'))='BOOLEAN' AND JSON_EXTRACT(NEW.receipt_json,'$.executionReady')=CAST('false' AS JSON) AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.externalAuthorityVerified'))='BOOLEAN' AND JSON_EXTRACT(NEW.receipt_json,'$.externalAuthorityVerified')=CAST('false' AS JSON) AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.allDomainsComplete'))='BOOLEAN' AND JSON_EXTRACT(NEW.receipt_json,'$.allDomainsComplete')=CAST('false' AS JSON) AND JSON_TYPE(JSON_EXTRACT(NEW.receipt_json,'$.contentPurgeExecuted'))='BOOLEAN' AND JSON_EXTRACT(NEW.receipt_json,'$.contentPurgeExecuted')=CAST('false' AS JSON) AND BINARY NEW.receipt_sha256=BINARY SHA2(CONCAT(NEW.scope,CHAR(0),CONCAT('{','"allDomainsComplete":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.allDomainsComplete') AS CHAR),',"catalogReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.catalogReceiptSha256') AS CHAR),',"cohortReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.cohortReceiptSha256') AS CHAR),',"completedClaimAttempt":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.completedClaimAttempt') AS CHAR),',"completedClaimTokenSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.completedClaimTokenSha256') AS CHAR),',"contentPurgeExecuted":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.contentPurgeExecuted') AS CHAR),',"databasePurgeGeneration":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.databasePurgeGeneration') AS CHAR),',"entryCount":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.entryCount') AS CHAR),',"entryRootSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.entryRootSha256') AS CHAR),',"executionGeneration":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.executionGeneration') AS CHAR),',"executionReady":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.executionReady') AS CHAR),',"externalAuthorityVerified":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.externalAuthorityVerified') AS CHAR),',"graveMarkerRootSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.graveMarkerRootSha256') AS CHAR),',"localPhysicalAckReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.localPhysicalAckReceiptSha256') AS CHAR),',"ownerClosureReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.ownerClosureReceiptSha256') AS CHAR),',"planBuildGeneration":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.planBuildGeneration') AS CHAR),',"planReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.planReceiptSha256') AS CHAR),',"preDeleteReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.preDeleteReceiptSha256') AS CHAR),',"requestId":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.requestId') AS CHAR),',"scope":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.scope') AS CHAR),',"sourceHighWaterDbMs":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.sourceHighWaterDbMs') AS CHAR),',"storeDbTimestampMs":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.storeDbTimestampMs') AS CHAR),',"subjectGeneration":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.subjectGeneration') AS CHAR),',"t1FenceSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.t1FenceSha256') AS CHAR),',"t1ProfileSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.t1ProfileSha256') AS CHAR),',"t3fReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.t3fReceiptSha256') AS CHAR),',"tenantId":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.tenantId') AS CHAR),',"usageReleaseReceiptSha256":',CAST(JSON_EXTRACT(NEW.receipt_json,'$.usageReleaseReceiptSha256') AS CHAR),'}')),256) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source JSON projection is invalid'; END IF; END;
DROP TRIGGER IF EXISTS trg_tt_retained_canonical_receipts_bu;
CREATE TRIGGER trg_tt_retained_canonical_receipts_bu BEFORE UPDATE ON tenant_telemetry_retained_source_canonical_receipts FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source evidence is immutable';
DROP TRIGGER IF EXISTS trg_tt_retained_canonical_receipts_bd;
CREATE TRIGGER trg_tt_retained_canonical_receipts_bd BEFORE DELETE ON tenant_telemetry_retained_source_canonical_receipts FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source evidence is append-only';

-- Family selection is immutable and is never inferred from an empty/missing receipt.
-- Admission precedes its cohort (the latter has an admission FK); the credential-job
-- guard is the downstream same-transaction publication boundary, including empty cohorts.
CREATE TRIGGER trg_tt_retained_admission_bi BEFORE INSERT ON tenant_erasure_admissions FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE BINARY domain=BINARY 'logs' AND state='active' AND control_generation=1 FOR SHARE) THEN IF (BINARY NEW.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1') IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='active capture admission requires retained-source protocol'; END IF; ELSEIF NEW.telemetry_retained_source_protocol IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='inactive capture admission cannot select retained-source protocol'; END IF; END;
CREATE TRIGGER trg_tt_retained_admission_bu BEFORE UPDATE ON tenant_erasure_admissions FOR EACH ROW BEGIN IF (BINARY OLD.telemetry_retained_source_protocol <=> BINARY NEW.telemetry_retained_source_protocol) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source admission protocol is immutable'; END IF; END;
CREATE TRIGGER trg_tt_retained_plan_bi BEFORE INSERT ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE BINARY a.request_id=BINARY NEW.request_id AND BINARY a.tenant_id=BINARY NEW.tenant_id AND a.subject_generation=NEW.subject_generation AND (BINARY a.telemetry_retained_source_protocol <=> BINARY NEW.telemetry_retained_source_protocol) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source plan family differs from admission'; END IF; IF NEW.telemetry_retained_source_protocol IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM tenant_telemetry_retained_source_t1_receipts r WHERE BINARY r.request_id=BINARY NEW.request_id AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND BINARY r.t1_fence_sha256=BINARY NEW.t1_fence_sha256 FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source plan lacks frozen T1 cohort'; END IF; END;
CREATE TRIGGER trg_tt_retained_plan_bu BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF (BINARY OLD.telemetry_retained_source_protocol <=> BINARY NEW.telemetry_retained_source_protocol) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source plan protocol is immutable'; END IF; END;
CREATE TRIGGER trg_tt_retained_credential_job_bi BEFORE INSERT ON tenant_credential_revocation_jobs FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE BINARY a.request_id=BINARY NEW.request_id AND BINARY a.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_t1_receipts r JOIN tenant_erasure_admissions a ON BINARY a.request_id=BINARY r.request_id JOIN tenant_credential_revocation_fences f ON BINARY f.request_id=BINARY a.request_id WHERE BINARY r.request_id=BINARY NEW.request_id AND BINARY r.tenant_id=BINARY NEW.tenant_id AND BINARY a.tenant_id=BINARY NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND a.subject_generation=NEW.subject_generation AND f.subject_generation=NEW.subject_generation AND BINARY r.t1_fence_sha256=BINARY NEW.t1_fence_sha256 AND BINARY f.evidence_sha256=BINARY NEW.t1_fence_sha256 AND r.store_db_timestamp_ms<=NEW.created_at_ms FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source T1 publication lacks whole cohort'; END IF; END;

-- Each leaf is anchored to actual rows. Nullable unknowns do not become executable
-- targets and must still describe a physically present managed source group.
-- A new tenant's two creation coverages share subject_lifecycle.created_at_ms,
-- floored by both activations; tenants.created_at_ms is its later profile timestamp.
-- The eligible receipt must preserve that exact birth anchor, not infer coverage
-- was created after the profile or accept a later backfilled coverage.
CREATE TRIGGER trg_tt_retained_t1_entries_source_bi BEFORE INSERT ON tenant_telemetry_retained_source_t1_entries FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF (NEW.captured_at_db_ms>=NEW.source_high_water_db_ms AND NEW.captured_at_db_ms<=db_now AND EXISTS (SELECT 1 FROM tenant_erasure_admissions a JOIN tenant_credential_revocation_fences f ON BINARY f.request_id=BINARY a.request_id JOIN tenant_telemetry_lifecycle_subjects s ON BINARY s.request_id=BINARY a.request_id WHERE BINARY a.request_id=BINARY NEW.request_id AND BINARY a.tenant_id=BINARY NEW.tenant_id AND BINARY a.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND a.subject_generation=NEW.subject_generation AND f.subject_generation=NEW.subject_generation AND BINARY f.tenant_id=BINARY NEW.tenant_id AND BINARY f.evidence_sha256=BINARY NEW.t1_fence_sha256 AND BINARY s.tenant_id=BINARY NEW.tenant_id AND s.subject_generation=NEW.subject_generation AND BINARY s.t1_fence_sha256=BINARY NEW.t1_fence_sha256 AND s.bound_at_db_ms<=NEW.captured_at_db_ms FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_jobs j WHERE BINARY j.request_id=BINARY NEW.request_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_t1_receipts r WHERE BINARY r.request_id=BINARY NEW.request_id FOR SHARE) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source cohort leaf lacks live T1 boundary'; END IF; IF NEW.write_operation_sha256 IS NULL THEN IF (NEW.state='unknown' AND EXISTS (SELECT 1 FROM tenant_telemetry_artifact_inventory i WHERE BINARY i.tenant_id=BINARY NEW.tenant_id AND BINARY i.inventory_sha256=BINARY NEW.inventory_sha256 AND i.source_schema='provider-step-error-v2' AND BINARY i.receipt_sha256=BINARY NEW.inventory_receipt_sha256 AND BINARY NEW.source_identity_sha256=BINARY SHA2(CONCAT('tenant-telemetry-retained-source-orphan-v1',CHAR(0),'[',JSON_QUOTE(NEW.tenant_id),',"inventory",',JSON_QUOTE(i.inventory_sha256),']'),256) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_write_jobs j WHERE BINARY j.inventory_sha256=BINARY i.inventory_sha256) AND NEW.source_high_water_db_ms>=GREATEST(i.source_high_water_db_ms,i.created_at_db_ms,i.restore_updated_at_db_ms) FOR SHARE) AND NEW.failure_commit_receipt_sha256 IS NULL AND NEW.source_binding_receipt_sha256 IS NULL AND NEW.membership_sha256 IS NULL AND NEW.write_job_evidence_sha256 IS NULL AND NEW.reservation_sha256 IS NULL AND NEW.write_ack_receipt_sha256 IS NULL AND NEW.payload_sha256 IS NULL) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source orphan cohort is not exact'; END IF; ELSE IF (BINARY NEW.source_identity_sha256=BINARY SHA2(CONCAT('tenant-telemetry-retained-source-managed-operation-v1',CHAR(0),'[',JSON_QUOTE(NEW.tenant_id),',',JSON_QUOTE(NEW.write_operation_sha256),']'),256) AND (EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_source_bindings b WHERE BINARY b.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY b.tenant_id=BINARY NEW.tenant_id FOR SHARE) OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_failure_commit_receipts f WHERE BINARY f.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY f.tenant_id=BINARY NEW.tenant_id FOR SHARE) OR EXISTS (SELECT 1 FROM tenant_telemetry_write_jobs j WHERE BINARY j.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY j.tenant_id=BINARY NEW.tenant_id AND JSON_UNQUOTE(JSON_EXTRACT(j.inventory_json,'$.sourceSchema'))='provider-step-error-v2' FOR SHARE) OR EXISTS (SELECT 1 FROM tenant_telemetry_artifact_memberships m WHERE BINARY m.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY m.tenant_id=BINARY NEW.tenant_id AND m.source_schema='provider-step-error-v2' FOR SHARE) OR EXISTS (SELECT 1 FROM tenant_telemetry_write_acks a WHERE BINARY a.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY a.tenant_id=BINARY NEW.tenant_id AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_write_jobs j WHERE BINARY j.write_operation_sha256=BINARY a.write_operation_sha256) FOR SHARE)) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source operation cohort lacks physical source'; END IF; IF (NEW.failure_commit_receipt_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_failure_commit_receipts f WHERE BINARY f.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY f.tenant_id=BINARY NEW.tenant_id AND BINARY f.receipt_sha256=BINARY NEW.failure_commit_receipt_sha256 AND JSON_EXTRACT(f.receipt_json,'$.committedAtDbMs')<=NEW.source_high_water_db_ms FOR SHARE)) IS NOT TRUE OR (NEW.source_binding_receipt_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_source_bindings b WHERE BINARY b.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY b.tenant_id=BINARY NEW.tenant_id AND BINARY b.receipt_sha256=BINARY NEW.source_binding_receipt_sha256 AND b.bound_at_db_ms<=NEW.source_high_water_db_ms FOR SHARE)) IS NOT TRUE OR (NEW.membership_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_artifact_memberships m WHERE BINARY m.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY m.tenant_id=BINARY NEW.tenant_id AND BINARY m.membership_sha256=BINARY NEW.membership_sha256 AND GREATEST(m.source_high_water_db_ms,m.inventory_created_at_db_ms)<=NEW.source_high_water_db_ms FOR SHARE)) IS NOT TRUE OR (NEW.write_ack_receipt_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_write_acks a WHERE BINARY a.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY a.tenant_id=BINARY NEW.tenant_id AND BINARY a.receipt_sha256=BINARY NEW.write_ack_receipt_sha256 AND a.store_db_timestamp_ms<=NEW.source_high_water_db_ms FOR SHARE)) IS NOT TRUE OR (NEW.inventory_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_artifact_inventory i WHERE BINARY i.inventory_sha256=BINARY NEW.inventory_sha256 AND BINARY i.tenant_id=BINARY NEW.tenant_id AND BINARY i.receipt_sha256=BINARY NEW.inventory_receipt_sha256 AND GREATEST(i.source_high_water_db_ms,i.created_at_db_ms,i.restore_updated_at_db_ms)<=NEW.source_high_water_db_ms FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source cohort scalar differs from physical source'; END IF; IF NEW.state<>'unknown' AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_write_jobs j JOIN tenant_telemetry_capture_v2_source_bindings b ON BINARY b.write_operation_sha256=BINARY j.write_operation_sha256 JOIN tenant_telemetry_capture_v2_failure_commit_receipts f ON BINARY f.write_operation_sha256=BINARY j.write_operation_sha256 JOIN tenant_telemetry_artifact_memberships m ON BINARY m.write_operation_sha256=BINARY j.write_operation_sha256 LEFT JOIN tenant_telemetry_write_acks a ON BINARY a.write_operation_sha256=BINARY j.write_operation_sha256 LEFT JOIN tenant_telemetry_artifact_inventory i ON BINARY i.inventory_sha256=BINARY j.inventory_sha256 LEFT JOIN tenant_telemetry_write_payloads p ON BINARY p.write_operation_sha256=BINARY j.write_operation_sha256 WHERE BINARY j.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY j.tenant_id=BINARY NEW.tenant_id AND BINARY b.tenant_id=BINARY NEW.tenant_id AND BINARY f.tenant_id=BINARY NEW.tenant_id AND BINARY m.tenant_id=BINARY NEW.tenant_id AND BINARY b.receipt_sha256=BINARY NEW.source_binding_receipt_sha256 AND BINARY f.receipt_sha256=BINARY NEW.failure_commit_receipt_sha256 AND BINARY m.membership_sha256=BINARY NEW.membership_sha256 AND NEW.write_job_evidence_sha256 IS NOT NULL AND BINARY j.payload_sha256=BINARY NEW.payload_sha256 AND BINARY b.payload_sha256=BINARY j.payload_sha256 AND BINARY m.payload_sha256=BINARY j.payload_sha256 AND BINARY m.inventory_sha256=BINARY j.inventory_sha256 AND (BINARY j.mutation_reservation_receipt_sha256 <=> BINARY NEW.reservation_sha256) AND GREATEST(j.created_at_ms,j.updated_at_ms,COALESCE(j.mutation_started_at_db_ms,0),COALESCE(j.written_at_db_ms,0),COALESCE(j.blocked_at_db_ms,0))<=NEW.source_high_water_db_ms AND ((NEW.state='written_ack' AND j.phase='written' AND BINARY a.tenant_id=BINARY NEW.tenant_id AND BINARY a.receipt_sha256=BINARY NEW.write_ack_receipt_sha256 AND BINARY a.receipt_sha256=BINARY j.write_ack_receipt_sha256 AND BINARY a.reservation_receipt_sha256=BINARY NEW.reservation_sha256 AND BINARY i.tenant_id=BINARY NEW.tenant_id AND BINARY i.inventory_sha256=BINARY NEW.inventory_sha256 AND BINARY i.receipt_sha256=BINARY NEW.inventory_receipt_sha256 AND BINARY a.inventory_receipt_sha256=BINARY i.receipt_sha256 AND p.write_operation_sha256 IS NULL) OR (NEW.state='blocked' AND j.phase='blocked' AND a.write_operation_sha256 IS NULL) OR (NEW.state IN ('pending','reserved') AND j.phase='queued' AND BINARY p.tenant_id=BINARY NEW.tenant_id AND BINARY p.payload_sha256=BINARY NEW.payload_sha256 AND a.write_operation_sha256 IS NULL AND ((NEW.state='pending' AND j.mutation_reservation_receipt_sha256 IS NULL) OR (NEW.state='reserved' AND j.mutation_reservation_receipt_sha256 IS NOT NULL)))) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source cohort state differs from live write graph'; END IF; END IF; END;

