(t.source_kind='persisted-provider-v2' AND (NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_catalog_sources e WHERE BINARY e.request_id=BINARY t.request_id AND BINARY e.artifact_group_sha256=BINARY t.artifact_group_sha256 AND e.source_kind='provider_source_binding' AND BINARY e.source_evidence_sha256=BINARY t.source_binding_receipt_sha256) OR NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_catalog_sources e WHERE BINARY e.request_id=BINARY t.request_id AND BINARY e.artifact_group_sha256=BINARY t.artifact_group_sha256 AND e.source_kind='provider_failure_commit' AND BINARY e.source_evidence_sha256=BINARY t.failure_commit_receipt_sha256)))) FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_artifact_inventory i LEFT JOIN tenant_telemetry_retained_source_catalog_sources e ON BINARY e.request_id=BINARY NEW.request_id AND e.source_kind='inventory' AND BINARY e.source_identity_sha256=BINARY i.inventory_sha256 WHERE BINARY i.tenant_id=BINARY NEW.tenant_id AND e.request_id IS NULL FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_write_jobs j LEFT JOIN tenant_telemetry_retained_source_catalog_sources e ON BINARY e.request_id=BINARY NEW.request_id AND e.source_kind='write_job' AND BINARY e.source_identity_sha256=BINARY j.write_operation_sha256 WHERE BINARY j.tenant_id=BINARY NEW.tenant_id AND e.request_id IS NULL FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_write_acks a LEFT JOIN tenant_telemetry_retained_source_catalog_sources e ON BINARY e.request_id=BINARY NEW.request_id AND e.source_kind='write_ack' AND BINARY e.source_identity_sha256=BINARY a.write_operation_sha256 WHERE BINARY a.tenant_id=BINARY NEW.tenant_id AND e.request_id IS NULL FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_artifact_memberships m LEFT JOIN tenant_telemetry_retained_source_catalog_sources e ON BINARY e.request_id=BINARY NEW.request_id AND e.source_kind='membership' AND BINARY e.source_identity_sha256=BINARY m.write_operation_sha256 WHERE 