CREATE TRIGGER trg_tt_retained_usage_entries_source_bi BEFORE INSERT ON tenant_telemetry_retained_source_usage_entries FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF (NEW.source_high_water_db_ms<=NEW.released_at_db_ms AND NEW.released_at_db_ms<=db_now AND EXISTS (SELECT 1 FROM tenant_purge_execution_jobs j JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_purge_plan_entries d ON BINARY d.request_id=BINARY j.request_id AND d.build_generation=j.plan_build_generation AND d.domain='operational_usage' JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_targets t ON BINARY t.request_id=BINARY j.request_id AND BINARY t.write_operation_sha256=BINARY NEW.write_operation_sha256 JOIN retention_policy_controls q ON BINARY q.tenant_id=BINARY j.tenant_id JOIN tenant_restore_runtime_control z ON z.singleton_id=1 AND z.state='active' AND z.lineage_kind='primary' JOIN tenant_telemetry_capture_v2_activation_receipts a ON a.domain='logs' WHERE BINARY j.request_id=BINARY NEW.request_id AND BINARY j.tenant_id=BINARY NEW.tenant_id AND j.subject_generation=NEW.subject_generation AND j.plan_build_generation=NEW.plan_build_generation AND j.execution_generation=NEW.execution_generation AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND j.attempts=NEW.completed_claim_attempt AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND BINARY NEW.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-purge-execution-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256) AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=NEW.released_at_db_ms AND BINARY j.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY p.tenant_id=BINARY NEW.tenant_id AND p.subject_generation=NEW.subject_generation AND p.build_generation=NEW.plan_build_generation AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND p.phase='plan_sealed' AND BINARY p.aggregate_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY d.tenant_id=BINARY NEW.tenant_id AND d.subject_generation=NEW.subject_generation AND d.disposition='anonymize' AND BINARY d.target_root_sha256=BINARY NEW.operational_usage_plan_root_sha256 AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND r.plan_build_generation=NEW.plan_build_generation AND BINARY r.receipt_sha256=BINARY NEW.catalog_receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY r.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY r.cohort_receipt_sha256=BINARY NEW.cohort_receipt_sha256 AND BINARY r.t1_profile_sha256=BINARY NEW.t1_profile_sha256 AND BINARY r.t1_fence_sha256=BINARY NEW.t1_fence_sha256 AND BINARY c.tenant_id=BINARY NEW.tenant_id AND c.subject_generation=NEW.subject_generation AND c.eligibility='eligible_retained' AND BINARY c.receipt_sha256=BINARY NEW.cohort_receipt_sha256 AND c.profile_kind='eligible-primary' AND BINARY t.receipt_sha256=BINARY NEW.catalog_entry_receipt_sha256 AND BINARY t.tenant_id=BINARY NEW.tenant_id AND t.subject_generation=NEW.subject_generation AND t.plan_build_generation=NEW.plan_build_generation AND t.source_kind='persisted-provider-v2' AND BINARY t.failure_commit_receipt_sha256=BINARY NEW.failure_commit_receipt_sha256 AND BINARY q.active_policy_sha256=BINARY j.policy_sha256 AND BINARY q.active_policy_version=BINARY p.policy_version AND BINARY z.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) AND BINARY z.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(a.receipt_json,'$.runtimeEpochSha256')) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeBindingSha256'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(a.receipt_json,'$.runtimeBindingSha256')) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.captureControlEvidenceSha256'))=BINARY a.receipt_sha256 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY NEW.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY NEW.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs r WHERE r.phase IN ('prepared','replay_sealed') FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE BINARY r.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_usage_receipts r WHERE BINARY r.request_id=BINARY NEW.request_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_purge_local_cutover_receipts r WHERE BINARY r.request_id=BINARY NEW.request_id FOR SHARE) AND EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_failure_commit_receipts f JOIN usage_ledger u ON BINARY u.tenant_id=BINARY f.tenant_id AND BINARY SHA2(CONCAT('tenant-telemetry-step-usage-id-v2',CHAR(0),JSON_QUOTE(u.usage_id)),256)=BINARY NEW.usage_id_sha256 JOIN billing_usage_facts b ON BINARY b.usage_id=BINARY u.usage_id AND BINARY b.tenant_id=BINARY u.tenant_id JOIN sessions s ON BINARY s.session_id=BINARY u.session_id AND BINARY s.user_id=BINARY u.user_id JOIN items i ON BINARY i.session_id=BINARY s.session_id AND BINARY i.user_id=BINARY s.user_id AND BINARY i.turn_id=BINARY u.turn_id WHERE BINARY f.write_operation_sha256=BINARY NEW.write_operation_sha256 AND BINARY f.tenant_id=BINARY NEW.tenant_id AND BINARY f.receipt_sha256=BINARY NEW.failure_commit_receipt_sha256 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(f.receipt_json,'$.usageIdSha256'))=BINARY NEW.usage_id_sha256 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(f.receipt_json,'$.billingRootSha256'))=BINARY NEW.billing_root_sha256 AND BINARY b.fact_sha256=BINARY NEW.retained_billing_fact_sha256 AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY i.telemetry_capture_v2_operation_sha256=BINARY f.write_operation_sha256 AND BINARY i.telemetry_capture_v2_failure_receipt_sha256=BINARY f.receipt_sha256 AND u.step=f.source_step_index AND JSON_EXTRACT(f.receipt_json,'$.committedAtDbMs')<=NEW.source_high_water_db_ms FOR SHARE) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source usage release lacks exact current source and claim'; END IF; END;

CREATE TRIGGER trg_tt_retained_usage_receipts_source_bi BEFORE INSERT ON tenant_telemetry_retained_source_usage_receipts FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF (NEW.source_high_water_db_ms<=NEW.store_db_timestamp_ms AND NEW.store_db_timestamp_ms<=db_now AND EXISTS (SELECT 1 FROM tenant_purge_execution_jobs j JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_purge_execution_domain_acks a ON BINARY a.request_id=BINARY j.request_id AND a.execution_generation=j.execution_generation AND a.domain='operational_usage' JOIN tenant_purge_local_cutover_receipts l ON BINARY l.request_id=BINARY j.request_id WHERE BINARY j.request_id=BINARY NEW.request_id AND BINARY j.tenant_id=BINARY NEW.tenant_id AND j.subject_generation=NEW.subject_generation AND j.plan_build_generation=NEW.plan_build_generation AND j.execution_generation=NEW.execution_generation AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND j.attempts=NEW.completed_claim_attempt AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND BINARY NEW.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-purge-execution-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256) AND BINARY j.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND r.plan_build_generation=NEW.plan_build_generation AND BINARY r.receipt_sha256=BINARY NEW.catalog_receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY r.cohort_receipt_sha256=BINARY NEW.cohort_receipt_sha256 AND BINARY r.t1_profile_sha256=BINARY NEW.t1_profile_sha256 AND BINARY r.t1_fence_sha256=BINARY NEW.t1_fence_sha256 AND BINARY c.receipt_sha256=BINARY NEW.cohort_receipt_sha256 AND c.eligibility='eligible_retained' AND BINARY a.receipt_sha256=BINARY NEW.operational_usage_ack_receipt_sha256 AND BINARY a.tenant_id=BINARY NEW.tenant_id AND a.subject_generation=NEW.subject_generation AND a.plan_build_generation=NEW.plan_build_generation AND a.ack_kind='anonymized' AND a.final=1 AND a.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY a.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 AND a.store_db_timestamp_ms<=NEW.store_db_timestamp_ms AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_usage_entries ack_leaf WHERE BINARY ack_leaf.request_id=BINARY NEW.request_id AND ack_leaf.released_at_db_ms>a.store_db_timestamp_ms FOR SHARE) AND BINARY l.receipt_sha256=BINARY NEW.local_cutover_receipt_sha256 AND BINARY l.tenant_id=BINARY NEW.tenant_id AND l.subject_generation=NEW.subject_generation AND l.plan_build_generation=NEW.plan_build_generation AND l.execution_generation=NEW.execution_generation AND BINARY l.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY l.operational_usage_target_root_sha256=BINARY NEW.operational_usage_plan_root_sha256 AND l.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY l.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 AND l.store_db_timestamp_ms=NEW.store_db_timestamp_ms AND l.all_domains_complete=0 AND l.content_purge_executed=0 AND r.persisted_provider_v2_count=NEW.entry_count FOR SHARE) AND (SELECT COUNT(*) FROM tenant_telemetry_retained_source_usage_entries e WHERE BINARY e.request_id=BINARY NEW.request_id)=NEW.entry_count AND NEW.retained_billing_fact_count=NEW.entry_count AND (SELECT COUNT(*) FROM billing_usage_facts b JOIN tenant_telemetry_retained_source_usage_entries e ON BINARY e.tenant_id=BINARY b.tenant_id AND BINARY e.retained_billing_fact_sha256=BINARY b.fact_sha256 AND BINARY e.usage_id_sha256=BINARY SHA2(CONCAT('tenant-telemetry-step-usage-id-v2',CHAR(0),JSON_QUOTE(b.usage_id)),256) WHERE BINARY e.request_id=BINARY NEW.request_id)=NEW.retained_billing_fact_count AND NOT EXISTS (SELECT 1 FROM usage_ledger u WHERE BINARY u.tenant_id=BINARY NEW.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_usage_entries e LEFT JOIN tenant_telemetry_retained_source_catalog_targets t ON BINARY t.request_id=BINARY e.request_id AND BINARY t.receipt_sha256=BINARY e.catalog_entry_receipt_sha256 LEFT JOIN billing_usage_facts b ON BINARY b.tenant_id=BINARY e.tenant_id AND BINARY SHA2(CONCAT('tenant-telemetry-step-usage-id-v2',CHAR(0),JSON_QUOTE(b.usage_id)),256)=BINARY e.usage_id_sha256 WHERE BINARY e.request_id=BINARY NEW.request_id AND (BINARY e.tenant_id<>BINARY NEW.tenant_id OR e.subject_generation<>NEW.subject_generation OR e.plan_build_generation<>NEW.plan_build_generation OR e.execution_generation<>NEW.execution_generation OR BINARY e.t1_profile_sha256<>BINARY NEW.t1_profile_sha256 OR BINARY e.t1_fence_sha256<>BINARY NEW.t1_fence_sha256 OR BINARY e.cohort_receipt_sha256<>BINARY NEW.cohort_receipt_sha256 OR BINARY e.catalog_receipt_sha256<>BINARY NEW.catalog_receipt_sha256 OR BINARY e.plan_receipt_sha256<>BINARY NEW.plan_receipt_sha256 OR BINARY e.operational_usage_plan_root_sha256<>BINARY NEW.operational_usage_plan_root_sha256 OR e.completed_claim_attempt<>NEW.completed_claim_attempt OR BINARY e.completed_claim_token_sha256<>BIN