CREATE TRIGGER trg_tt_retained_canonical_entries_source_bi BEFORE INSERT ON tenant_telemetry_retained_source_canonical_entries FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF (NEW.source_high_water_db_ms<=NEW.captured_at_db_ms AND NEW.captured_at_db_ms<=db_now AND EXISTS (SELECT 1 FROM tenant_database_purge_jobs j JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_entries v ON BINARY v.request_id=BINARY j.request_id AND BINARY v.write_operation_sha256=BINARY NEW.write_operation_sha256 JOIN tenant_telemetry_retained_source_catalog_targets t ON BINARY t.request_id=BINARY j.request_id AND BINARY t.write_operation_sha256=BINARY NEW.write_operation_sha256 JOIN tenant_telemetry_capture_v2_failure_commit_receipts f ON BINARY f.write_operation_sha256=BINARY NEW.write_operation_sha256 JOIN tenant_telemetry_capture_v2_source_bindings b ON BINARY b.write_operation_sha256=BINARY f.write_operation_sha256 JOIN tenant_telemetry_artifact_memberships m ON BINARY m.write_operation_sha256=BINARY f.write_operation_sha256 JOIN tenant_telemetry_owner_closure_entries o ON BINARY o.request_id=BINARY j.request_id AND BINARY o.write_operation_sha256=BINARY f.write_operation_sha256 JOIN tenant_purge_session_grave_markers g ON BINARY g.request_id=BINARY j.request_id AND BINARY g.marker_sha256=BINARY o.session_grave_marker_sha256 JOIN tenant_database_purge_predelete_receipts d ON BINARY d.request_id=BINARY j.request_id JOIN sessions s ON BINARY s.session_id=BINARY g.session_id JOIN items i ON BINARY i.session_id=BINARY s.session_id AND BINARY i.user_id=BINARY s.user_id AND BIN