n.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND BINARY NEW.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256) AND BINARY j.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY j.local_physical_ack_receipt_sha256=BINARY NEW.local_physical_ack_receipt_sha256 AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND BINARY c.receipt_sha256=BINARY NEW.cohort_receipt_sha256 AND c.eligibility='eligible_retained' AND BINARY c.t1_profile_sha256=BINARY NEW.t1_profile_sha256 AND BINARY c.t1_fence_sha256=BINARY NEW.t1_fence_sha256 AND BINARY r.receipt_sha256=BINARY NEW.catalog_receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY r.cohort_receipt_sha256=BINARY c.receipt_sha256 AND BINARY u.receipt_sha256=BINARY NEW.usage_release_receipt_sha256 AND BINARY u.catalog_receipt_sha256=BINARY r.receipt_sha256 AND u.entry_count=NEW.entry_count AND r.persisted_provider_v2_count=NEW.entry_count AND BINARY d.receipt_sha256=BINARY NEW.t3f_receipt_sha256 AND BINARY d.tenant_id=BINARY NEW.tenant_id AND d.subject_generation=NEW.subject_generation AND d.plan_build_generation=NEW.plan_build_generation AND d.execution_generation=NEW.execution_generation AND d.database_purge_generation=NEW.database_purge_generation AND BINARY d.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY d.local_physical_ack_receipt_sha256=BINARY NEW.local_physical_ack_receipt_sha256 AND BINARY d.predelete_receipt_sha256=BINARY NEW.predelete_receipt_sha256 AND BINARY d.grave_marker_root_sha256=BINARY NEW.grave_marker_root_sha256 AND d.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY d.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 AND d.store_db_timestamp_ms=NEW.store_db_timestamp_ms AND d.all_domains_complete=0 AND d.content_purge_executed=0 AND BINARY o.receipt_sha256=BINARY NEW.ow