.session_id WHERE BINARY g.request_id=BINARY NEW.request_id FOR SHARE) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source canonical closure lacks actual deletion and old receipts'; END IF; END;

-- Rotation fences are scoped verify-or-create statements in the migration executor.
-- Canonical pre-delete source preserves the published grave transformation:
-- live generation 0/NULL becomes grave 1/capture-time; an existing tombstone
-- keeps its exact nonzero generation/time. Neither branch treats NULL as a value.
-- Never DROP a surviving fence before its exact body is independently checked.
-- Both temporary fences precede the old primary DROP; the new primary precedes
-- removal of either fence. Keep all eight fences until every parent DELETE and
-- bottom-up root guard is installed; intermediate DDL prefixes remain hard denied.
CREATE TRIGGER trg_tt_retained_t3d_catalog_bootstrap_a BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='plan_sealed' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source catalog rotation is fenced'; END IF; END;
CREATE TRIGGER trg_tt_retained_t3d_catalog_bootstrap_b BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='plan_sealed' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source catalog rotation is fenced'; END IF; END;
DROP TRIGGER trg_tt_plan_artifact_target_t3d_terminal_bu;
CREATE TRIGGER trg_tt_plan_artifact_target_t3d_terminal_bu BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='plan_sealed' THEN IF NEW.telemetry_retained_source_protocol IS NULL THEN IF NOT EXISTS (SELECT 1 FROM tenant_telemetry_plan_artifact_target_receipts r JOIN tenant_telemetry_source_accounting_receipts s ON BINARY s.receipt_sha256=BINARY r.source_accounting_receipt_sha256 JOIN tenant_telemetry_target_manifest_receipts m ON BINARY m.receipt_sha256=BINARY r.target_manifest_receipt_sha256 WHERE BINARY r.request_id=BINARY NEW.request_id AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND r.build_generation=NEW.build_generation AND BINARY r.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY s.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY m.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY m.source_accounting_receipt_sha256=BINARY s.receipt_sha256 AND r.execution_ready=0 AND r.store_db_timestamp_ms>=NEW.sealed_at_ms AND r.store_db_timestamp_ms<=NEW.updated_at_ms AND r.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY r.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 AND (SELECT COUNT(*) FROM tenant_telemetry_plan_artifact_targets e WHERE BINARY e.request_id=BINARY r.request_id AND BINARY e.tenant_id=BINARY r.tenant_id)=r.target_count AND r.target_count=m.observed_target_count AND r.unknown_group_count=m.unknown_group_count) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='terminal T3d lacks immutable telemetry plan artifact target catalog'; END IF; ELSE IF (BINARY NEW.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND OLD.claim_token IS NOT NULL AND OLD.lease_until_ms>FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000) AND BINARY NEW.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-purge-plan-claim-token-v1",',JSON_QUOTE(OLD.claim_token),']'),256) AND EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_catalog_receipts r JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.receipt_sha256=BINARY r.cohort_receipt_sha256 JOIN tenant_telemetry_source_accounting_receipts s ON BINARY s.receipt_sha256=BINARY r.legacy_source_accounting_receipt_sha256 JOIN tenant_telemetry_target_manifest_receipts m ON BINARY m.receipt_sha256=BINARY r.legacy_target_manifest_receipt_sha256 WHERE BINARY r.request_id=BINARY NEW.request_id AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND r.plan_build_generation=NEW.build_generation AND BINARY r.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY r.t1_fence_sha256=BINARY NEW.t1_fence_sha256 AND BINARY c.request_id=BINARY NEW.request_id AND BINARY c.tenant_id=BINARY NEW.tenant_id AND c.subject_generation=NEW.subject_generation AND c.eligibility='eligible_retained' AND BINARY c.t1_profile_sha256=BINARY r.t1_profile_sha256 AND BINARY s.request_id=BINARY NEW.request_id AND BINARY m.request_id=BINARY NEW.request_id AND BINARY s.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY m.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY m.source_accounting_receipt_sha256=BINARY s.receipt_sha256 AND r.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY r.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 AND r.store_db_timestamp_ms>=NEW.sealed_at_ms AND r.store_db_timestamp_ms<=NEW.updated_at_ms AND (SELECT COUNT(*) FROM tenant_telemetry_retained_source_catalog_targets e WHERE BINARY e.request_id=BINARY r.request_id)=r.entry_count AND (SELECT COUNT(*) FROM tenant_telemetry_retained_source_catalog_sources e WHERE BINARY e.request_id=BINARY r.request_id)=r.source_count FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_plan_artifact_target_receipts r WHERE BINARY r.request_id=BINARY NEW.request_id FOR SHARE) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='terminal T3d lacks exact retained-source catalog'; END IF; END IF; END IF; END;

CREATE TRIGGER trg_tt_retained_t3d_capture_bootstrap_a BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='plan_sealed' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source capture T3d rotation is fenced'; END IF; END;
CREATE TRIGGER trg_tt_retained_t3d_capture_bootstrap_b BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='plan_sealed' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source capture T3d rotation is fenced'; END IF; END;
DROP TRIGGER trg_tt_capture_v2_t3d_bu;
CREATE TRIGGER trg_tt_capture_v2_t3d_bu BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='plan_sealed' AND (EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE state<>'inactive' OR control_generation<>0) OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_coverages WHERE BINARY tenant_id=BINARY NEW.tenant_id) OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_source_bindings WHERE BINARY tenant_id=BINARY NEW.tenant_id)) THEN IF (BINARY NEW.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_catalog_receipts r JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.receipt_sha256=BINARY r.cohort_receipt_sha256 WHERE BINARY r.request_id=BINARY NEW.request_id AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND r.plan_build_generation=NEW.build_generation AND BINARY r.plan_receipt_sha256=BINARY NEW.aggregate_receipt_sha256 AND BINARY c.request_id=BINARY NEW.request_id AND BINARY c.tenant_id=BINARY NEW.tenant_id AND c.subject_generation=NEW.subject_generation AND c.eligibility='eligible_retained' AND r.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY r.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='T3d cannot account for capture v2 source'; END IF; END IF; END;

CREATE TRIGGER trg_tt_retained_t3f_capture_bootstrap_a BEFORE UPDATE ON tenant_database_purge_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='database_purged' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source capture T3f rotation is fenced'; END IF; END;
CREATE TRIGGER trg_tt_retained_t3f_capture_bootstrap_b BEFORE UPDATE ON tenant_database_purge_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='database_purged' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source capture T3f rotation is fenced'; END IF; END;
DROP TRIGGER trg_tt_capture_v2_t3f_bu;
CREATE TRIGGER trg_tt_capture_v2_t3f_bu BEFORE UPDATE ON tenant_database_purge_jobs FOR EACH ROW BEGIN IF OLD.phase='queued' AND NEW.phase='database_purged' AND (EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE state<>'inactive' OR control_generation<>0) OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_coverages WHERE BINARY tenant_id=BINARY NEW.tenant_id) OR EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_source_bindings WHERE BINARY tenant_id=BINARY NEW.tenant_id)) THEN IF (OLD.claim_token IS NOT NULL AND OLD.lease_until_ms>FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000) AND BINARY NEW.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(OLD.claim_token),']'),256) AND EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_canonical_receipts r JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY r.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.receipt_sha256=BINARY r.cohort_receipt_sha256 JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.receipt_sha256=BINARY r.usage_release_receipt_sha256 JOIN tenant_telemetry_owner_closure_receipts o ON BINARY o.receipt_sha256=BINARY r.owner_closure_receipt_sha256 WHERE BINARY r.request_id=BINARY NEW.request_id AND BINARY r.tenant_id=BINARY NEW.tenant_id AND r.subject_generation=NEW.subject_generation AND r.plan_build_generation=NEW.plan_build_generation AND r.execution_generation=NEW.execution_generation AND r.database_purge_generation=NEW.database_purge_generation AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND c.eligibility='eligible_retained' AND BINARY r.t3f_receipt_sha256=BINARY NEW.terminal_receipt_sha256 AND BINARY r.predelete_receipt_sha256=BINARY NEW.predelete_receipt_sha256 AND BINARY r.plan_receipt_sha256=BINARY NEW.plan_receipt_sha256 AND BINARY r.local_physical_ack_receipt_sha256=BINARY NEW.local_physical_ack_receipt_sha256 AND BINARY o.t3f_receipt_sha256=BINARY NEW.terminal_receipt_sha256 AND r.completed_claim_attempt=NEW.completed_claim_attempt AND BINARY r.completed_claim_token_sha256=BINARY NEW.completed_claim_token_sha256 AND r.store_db_timestamp_ms=NEW.purged_at_db_ms AND r.entry_count=u.entry_count FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='T3f cannot close capture v2 owner source'; END IF; END IF; END;

CREATE TRIGGER trg_tt_retained_usage_delete_bootstrap_a BEFORE DELETE ON usage_ledger FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source usage rotation is fenced';
CREATE TRIGGER trg_tt_retained_usage_delete_bootstrap_b BEFORE DELETE ON usage_ledger FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='retained-source usage rotation is fenced';
DROP TRIGGER trg_tt_capture_v2_usage_bd;
CREATE TRIGGER trg_tt_capture_v2_usage_bd BEFORE DELETE ON usage_ledger FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_failure_commit_receipts f WHERE BINARY f.tenant_id=BINARY OLD.tenant_id AND OLD.usage_id IS NOT NULL AND BINARY JSON_UNQUOTE(JSON_EXTRACT(f.receipt_json,'$.usageIdSha256')) =BINARY SHA2(CONCAT('tenant-telemetry-step-usage-id-v2',CHAR(0),JSON_QUOTE(OLD.usage_id)),256) FOR SHARE) THEN IF (EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_usage_entries e JOIN tenant_purge_execution_jobs j ON BINARY j.request_id=BINARY e.request_id JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY e.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.receipt_sha256=BINARY e.cohort_receipt_sha256 JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.receipt_sha256=BINARY e.catalog_receipt_sha256 JOIN tenant_telemetry_capture_v2_failure_commit_receipts f ON BINARY f.write_operation_sha256=BINARY e.write_operation_sha256 JOIN billing_usage_facts b ON BINARY b.usage_id=BINARY OLD.usage_id AND BINARY b.tenant_id=BINARY OLD.tenant_id JOIN retention_policy_controls q ON BINARY q.tenant_id=BINARY OLD.tenant_id JOIN tenant_restore_runtime_control runtime ON runtime.singleton_id=1 AND runtime.state='active' AND runtime.lineage_kind='primary' WHERE BINARY e.tenant_id=BINARY OLD.tenant_id AND BINARY j.tenant_id=BINARY OLD.tenant_id AND BINARY p.tenant_id=BINARY OLD.tenant_id AND BINARY e.usage_id_sha256=BINARY SHA2(CONCAT('tenant-telemetry-step-usage-id-v2',CHAR(0),JSON_QUOTE(OLD.usage_id)),256) AND BINARY f.tenant_id=BINARY OLD.tenant_id AND BINARY f.receipt_sha256=BINARY e.failure_commit_receipt_sha256 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(f.receipt_json,'$.usageIdSha256'))=BINARY e.usage_id_sha256 AND BINARY b.fact_sha256=BINARY e.retained_billing_fact_sha256 AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND c.eligibility='eligible_retained' AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND j.subject_generation=e.subject_generation AND j.plan_build_generation=e.plan_build_generation AND j.execution_generation=e.execution_generation AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND j.attempts=e.completed_claim_attempt AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND BINARY e.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-purge-execution-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256) AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=db_now AND e.released_at_db_ms<=db_now AND BINARY q.active_policy_sha256=BINARY j.policy_sha256 AND BINARY q.active_policy_version=BINARY p.policy_version AND BINARY runtime.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY OLD.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY OLD.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs r WHERE r.phase IN ('prepared','replay_sealed') FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE BINARY r.tenant_id=BINARY OLD.tenant_id FOR SHARE) ) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='persisted provider failure usage source is retained'; END IF; END IF; END;

-- Canonical content remains protected while capture is active. A grave/pre-delete
-- snapshot and the complete eligible retained-source bridge must precede the first
-- DELETE. Parent guards independently enforce this: FK cascades do not fire child
-- DELETE triggers in MySQL. No session variable or caller-provided digest is a bypass.
CREATE TRIGGER trg_tt_retained_items_bd BEFORE DELETE ON items FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE domain='logs' AND state='active' AND control_generation=1 FOR SHARE) OR OLD.telemetry_capture_v2_operation_sha256 IS NOT NULL THEN IF OLD.type='agentMessage' AND OLD.status='failed' AND (OLD.telemetry_capture_v2_control_generation IS NULL OR OLD.telemetry_capture_v2_control_generation=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='legacy failed item source is retained'; END IF; IF NOT EXISTS (SELECT 1 FROM sessions s JOIN tenant_purge_session_grave_markers g ON BINARY g.session_id=BINARY s.session_id JOIN tenant_database_purge_jobs j ON BINARY j.request_id=BINARY g.request_id JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.request_id=BINARY j.request_id JOIN tenant_database_purge_predelete_receipts d ON BINARY d.request_id=BINARY j.request_id JOIN retention_policy_controls policy ON BINARY policy.tenant_id=BINARY j.tenant_id JOIN tenant_restore_runtime_control runtime ON runtime.singleton_id=1 AND runtime.state='active' AND runtime.lineage_kind='primary' WHERE BINARY s.session_id=BINARY OLD.session_id AND BINARY s.user_id=BINARY OLD.user_id AND BINARY g.tenant_id=BINARY s.tenant_id AND BINARY j.tenant_id=BINARY s.tenant_id AND j.subject_generation=g.subject_generation AND j.plan_build_generation=g.plan_build_generation AND j.execution_generation=g.execution_generation AND j.database_purge_generation=g.database_purge_generation AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=db_now AND j.predelete_receipt_sha256 IS NULL AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND BINARY c.tenant_id=BINARY s.tenant_id AND c.subject_generation=j.subject_generation AND c.eligibility='eligible_retained' AND BINARY r.cohort_receipt_sha256=BINARY c.receipt_sha256 AND BINARY r.tenant_id=BINARY s.tenant_id AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY u.catalog_receipt_sha256=BINARY r.receipt_sha256 AND BINARY u.tenant_id=BINARY s.tenant_id AND BINARY d.receipt_sha256=BINARY g.predelete_receipt_sha256 AND d.database_purge_generation=j.database_purge_generation AND BINARY policy.active_policy_sha256=BINARY j.policy_sha256 AND BINARY policy.active_policy_version=BINARY p.policy_version AND BINARY runtime.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY s.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY s.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences f WHERE BINARY f.tenant_id=BINARY s.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs run WHERE run.phase IN ('prepared','replay_sealed') FOR SHARE) AND (OLD.telemetry_capture_v2_operation_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_canonical_entries e WHERE BINARY e.request_id=BINARY j.request_id AND BINARY e.tenant_id=BINARY s.tenant_id AND e.subject_generation=j.subject_generation AND e.plan_build_generation=j.plan_build_generation AND e.execution_generation=j.execution_generation AND e.database_purge_generation=j.database_purge_generation AND BINARY e.write_operation_sha256=BINARY OLD.telemetry_capture_v2_operation_sha256 AND BINARY e.failure_commit_receipt_sha256=BINARY OLD.telemetry_capture_v2_failure_receipt_sha256 AND BINARY e.business_batch_sha256=BINARY OLD.telemetry_capture_v2_business_batch_sha256 AND BINARY e.source_session_ref_sha256=BINARY OLD.telemetry_capture_v2_session_ref_sha256 AND BINARY e.source_turn_ref_sha256=BINARY OLD.telemetry_capture_v2_turn_ref_sha256 AND BINARY e.source_item_ref_sha256=BINARY OLD.telemetry_capture_v2_item_ref_sha256 AND BINARY e.session_grave_marker_sha256=BINARY g.marker_sha256 AND BINARY e.predelete_receipt_sha256=BINARY d.receipt_sha256 AND e.completed_claim_attempt=j.attempts AND BINARY e.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256))) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='canonical item deletion lacks retained-source pre-delete bridge'; END IF; END IF; END;

CREATE TRIGGER trg_tt_retained_events_bd BEFORE DELETE ON events FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE domain='logs' AND state='active' AND control_generation=1 FOR SHARE) OR OLD.telemetry_capture_v2_operation_sha256 IS NOT NULL THEN IF OLD.type='item/completed' AND JSON_UNQUOTE(JSON_EXTRACT(OLD.body,'$.item.type'))='agentMessage' AND JSON_UNQUOTE(JSON_EXTRACT(OLD.body,'$.item.status'))='failed' AND (OLD.telemetry_capture_v2_control_generation IS NULL OR OLD.telemetry_capture_v2_control_generation=0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='legacy failed event source is retained'; END IF; IF NOT EXISTS (SELECT 1 FROM tenant_purge_session_grave_markers g JOIN tenant_database_purge_jobs j ON BINARY j.request_id=BINARY g.request_id JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.request_id=BINARY j.request_id JOIN tenant_database_purge_predelete_receipts d ON BINARY d.request_id=BINARY j.request_id JOIN retention_policy_controls policy ON BINARY policy.tenant_id=BINARY j.tenant_id JOIN tenant_restore_runtime_control runtime ON runtime.singleton_id=1 AND runtime.state='active' AND runtime.lineage_kind='primary' WHERE BINARY g.session_id=BINARY OLD.session_id AND BINARY g.tenant_id=BINARY j.tenant_id AND j.subject_generation=g.subject_generation AND j.plan_build_generation=g.plan_build_generation AND j.execution_generation=g.execution_generation AND j.database_purge_generation=g.database_purge_generation AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND j.predelete_receipt_sha256 IS NULL AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=db_now AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND c.eligibility='eligible_retained' AND BINARY r.cohort_receipt_sha256=BINARY c.receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY u.catalog_receipt_sha256=BINARY r.receipt_sha256 AND BINARY d.receipt_sha256=BINARY g.predelete_receipt_sha256 AND BINARY policy.active_policy_sha256=BINARY j.policy_sha256 AND BINARY policy.active_policy_version=BINARY p.policy_version AND BINARY runtime.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY j.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY j.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences f WHERE BINARY f.tenant_id=BINARY j.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs run WHERE run.phase IN ('prepared','replay_sealed') FOR SHARE) AND (OLD.telemetry_capture_v2_operation_sha256 IS NULL OR EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_canonical_entries e WHERE BINARY e.request_id=BINARY j.request_id AND BINARY e.session_grave_marker_sha256=BINARY g.marker_sha256 AND BINARY e.write_operation_sha256=BINARY OLD.telemetry_capture_v2_operation_sha256 AND BINARY e.failure_commit_receipt_sha256=BINARY OLD.telemetry_capture_v2_failure_receipt_sha256 AND e.source_event_seq=OLD.seq AND e.completed_claim_attempt=j.attempts AND BINARY e.completed_claim_token_sha256=BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256))) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_failure_commit_receipts f JOIN items i ON BINARY i.telemetry_capture_v2_operation_sha256=BINARY f.write_operation_sha256 LEFT JOIN tenant_telemetry_retained_source_canonical_entries e ON BINARY e.request_id=BINARY j.request_id AND BINARY e.write_operation_sha256=BINARY f.write_operation_sha256 WHERE BINARY i.session_id=BINARY OLD.session_id AND OLD.seq>f.begin_last_seq AND OLD.seq<=f.end_last_seq AND (e.request_id IS NULL OR BINARY e.failure_commit_receipt_sha256<>BINARY f.receipt_sha256 OR BINARY e.session_grave_marker_sha256<>BINARY g.marker_sha256)) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_canonical_entries e WHERE BINARY e.session_grave_marker_sha256=BINARY g.marker_sha256 AND OLD.seq>e.begin_last_seq AND OLD.seq<=e.end_last_seq AND (BINARY e.request_id<>BINARY j.request_id OR e.completed_claim_attempt<>j.attempts OR BINARY e.completed_claim_token_sha256<>BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256))) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='canonical event deletion lacks retained-source pre-delete bridge'; END IF; END IF; END;

CREATE TRIGGER trg_tt_retained_turns_bd BEFORE DELETE ON turns FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE domain='logs' AND state='active' AND control_generation=1 FOR SHARE) THEN IF EXISTS (SELECT 1 FROM items i WHERE BINARY i.turn_id=BINARY OLD.turn_id AND i.type='agentMessage' AND i.status='failed' AND (i.telemetry_capture_v2_control_generation IS NULL OR i.telemetry_capture_v2_control_generation=0) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='legacy failed turn source is retained'; END IF; IF NOT EXISTS (SELECT 1 FROM tenant_purge_session_grave_markers g JOIN tenant_database_purge_jobs j ON BINARY j.request_id=BINARY g.request_id JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.request_id=BINARY j.request_id JOIN tenant_database_purge_predelete_receipts d ON BINARY d.request_id=BINARY j.request_id JOIN retention_policy_controls policy ON BINARY policy.tenant_id=BINARY j.tenant_id JOIN tenant_restore_runtime_control runtime ON runtime.singleton_id=1 AND runtime.state='active' AND runtime.lineage_kind='primary' WHERE BINARY g.session_id=BINARY OLD.session_id AND BINARY g.tenant_id=BINARY j.tenant_id AND j.subject_generation=g.subject_generation AND j.plan_build_generation=g.plan_build_generation AND j.execution_generation=g.execution_generation AND j.database_purge_generation=g.database_purge_generation AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND j.predelete_receipt_sha256 IS NULL AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=db_now AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND c.eligibility='eligible_retained' AND BINARY r.cohort_receipt_sha256=BINARY c.receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY u.catalog_receipt_sha256=BINARY r.receipt_sha256 AND BINARY d.receipt_sha256=BINARY g.predelete_receipt_sha256 AND BINARY policy.active_policy_sha256=BINARY j.policy_sha256 AND BINARY policy.active_policy_version=BINARY p.policy_version AND BINARY runtime.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY j.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY j.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences f WHERE BINARY f.tenant_id=BINARY j.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs run WHERE run.phase IN ('prepared','replay_sealed') FOR SHARE) AND NOT EXISTS (SELECT 1 FROM items i LEFT JOIN tenant_telemetry_retained_source_canonical_entries e ON BINARY e.request_id=BINARY j.request_id AND BINARY e.write_operation_sha256=BINARY i.telemetry_capture_