CREATE TRIGGER trg_tt_retained_sessions_bd BEFORE DELETE ON sessions FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE domain='logs' AND state='active' AND control_generation=1 FOR SHARE) THEN IF EXISTS (SELECT 1 FROM items i WHERE BINARY i.session_id=BINARY OLD.session_id AND i.type='agentMessage' AND i.status='failed' AND (i.telemetry_capture_v2_control_generation IS NULL OR i.telemetry_capture_v2_control_generation=0) FOR SHARE) OR EXISTS (SELECT 1 FROM events e WHERE BINARY e.session_id=BINARY OLD.session_id AND e.type='item/completed' AND JSON_UNQUOTE(JSON_EXTRACT(e.body,'$.item.type'))='agentMessage' AND JSON_UNQUOTE(JSON_EXTRACT(e.body,'$.item.status'))='failed' AND (e.telemetry_capture_v2_control_generation IS NULL OR e.telemetry_capture_v2_control_generation=0) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='legacy failed session source is retained'; END IF; IF NOT EXISTS (SELECT 1 FROM tenant_purge_session_grave_markers g JOIN tenant_database_purge_jobs j ON BINARY j.request_id=BINARY g.request_id JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.request_id=BINARY j.request_id JOIN tenant_database_purge_predelete_receipts d ON BINARY d.request_id=BINARY j.request_id JOIN retention_policy_controls policy ON BINARY policy.tenant_id=BINARY j.tenant_id JOIN tenant_restore_runtime_control runtime ON runtime.singleton_id=1 AND runtime.state='active' AND runtime.lineage_kind='primary' WHERE BINARY g.session_id=BINARY OLD.session_id AND BINARY g.tenant_id=BINARY OLD.tenant_id AND BINARY j.tenant_id=BINARY OLD.tenant_id AND j.subject_generation=g.subject_generation AND j.plan_build_generation=g.plan_build_generation AND j.execution_generation=g.execution_generation AND j.database_purge_generation=g.database_purge_generation AND g.marked_at_db_ms=d.store_db_timestamp_ms AND ((OLD.deletion_generation=0 AND OLD.deleted_at_ms IS NULL AND g.deletion_generation=1 AND g.deleted_at_db_ms=g.marked_at_db_ms) OR (OLD.deletion_generation>0 AND OLD.deleted_at_ms IS NOT NULL AND g.deletion_generation=OLD.deletion_generation AND g.deleted_at_db_ms=OLD.deleted_at_ms)) AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND j.predelete_receipt_sha256 IS NULL AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=db_now AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND c.eligibility='eligible_retained' AND BINARY r.cohort_receipt_sha256=BINARY c.receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY u.catalog_receipt_sha256=BINARY r.receipt_sha256 AND BINARY d.receipt_sha256=BINARY g.predelete_receipt_sha256 AND BINARY policy.active_policy_sha256=BINARY j.policy_sha256 AND BINARY policy.active_policy_version=BINARY p.policy_version AND BINARY runtime.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY OLD.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY OLD.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences f WHERE BINARY f.tenant_id=BINARY OLD.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs run WHERE run.phase IN ('prepared','replay_sealed') FOR SHARE) AND NOT EXISTS (SELECT 1 FROM items i LEFT JOIN tenant_telemetry_retained_source_canonical_entries e ON BINARY e.request_id=BINARY j.request_id AND BINARY e.write_operation_sha256=BINARY i.telemetry_capture_v2_operation_sha256 WHERE BINARY i.session_id=BINARY OLD.session_id AND i.telemetry_capture_v2_operation_sha256 IS NOT NULL AND (e.request_id IS NULL OR BINARY e.session_grave_marker_sha256<>BINARY g.marker_sha256)) AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_canonical_entries e WHERE BINARY e.session_grave_marker_sha256=BINARY g.marker_sha256 AND (BINARY e.request_id<>BINARY j.request_id OR e.completed_claim_attempt<>j.attempts OR BINARY e.completed_claim_token_sha256<>BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256))) AND NOT EXISTS (SELECT 1 FROM sessions child LEFT JOIN tenant_purge_session_grave_markers child_grave ON BINARY child_grave.session_id=BINARY child.session_id AND BINARY child_grave.request_id=BINARY j.request_id WHERE BINARY child.parent_session_id=BINARY OLD.session_id AND child_grave.session_id IS NULL) FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='canonical session parent deletion lacks retained-source bridge'; END IF; END IF; END;

CREATE TRIGGER trg_tt_retained_tenants_bd BEFORE DELETE ON tenants FOR EACH ROW BEGIN DECLARE db_now BIGINT UNSIGNED; SET db_now=FLOOR(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000); IF EXISTS (SELECT 1 FROM tenant_telemetry_capture_v2_controls WHERE domain='logs' AND state='active' AND control_generation=1 FOR SHARE) THEN IF (NOT EXISTS (SELECT 1 FROM sessions s WHERE BINARY s.tenant_id=BINARY OLD.tenant_id FOR SHARE) AND EXISTS (SELECT 1 FROM tenant_database_purge_jobs j JOIN tenant_purge_plan_jobs p ON BINARY p.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_t1_receipts c ON BINARY c.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_catalog_receipts r ON BINARY r.request_id=BINARY j.request_id JOIN tenant_telemetry_retained_source_usage_receipts u ON BINARY u.request_id=BINARY j.request_id JOIN tenant_database_purge_predelete_receipts d ON BINARY d.request_id=BINARY j.request_id JOIN retention_policy_controls policy ON BINARY policy.tenant_id=BINARY j.tenant_id JOIN tenant_restore_runtime_control runtime ON runtime.singleton_id=1 AND runtime.state='active' AND runtime.lineage_kind='primary' WHERE BINARY j.tenant_id=BINARY OLD.tenant_id AND j.phase='queued' AND j.claim_token IS NOT NULL AND j.lease_until_ms>db_now AND (SELECT COUNT(*) FROM tenant_purge_plan_entries full_plan WHERE BINARY full_plan.request_id=BINARY j.request_id AND BINARY full_plan.tenant_id=BINARY j.tenant_id AND full_plan.subject_generation=j.subject_generation AND full_plan.build_generation=j.plan_build_generation)=33 AND NOT EXISTS (SELECT 1 FROM tenant_purge_plan_entries external_plan WHERE BINARY external_plan.request_id=BINARY j.request_id AND BINARY external_plan.tenant_id=BINARY j.tenant_id AND external_plan.subject_generation=j.subject_generation AND external_plan.build_generation=j.plan_build_generation AND (LEFT(external_plan.domain,5)='blob_' OR LEFT(external_plan.domain,12)='user_export_') AND (external_plan.target_count=0) IS NOT TRUE FOR SHARE) AND j.predelete_receipt_sha256 IS NULL AND GREATEST(j.purge_not_before_db_ms,j.source_evidence_db_ms)<=db_now AND BINARY p.telemetry_retained_source_protocol=BINARY 'tenant-telemetry-retained-source-v1' AND c.eligibility='eligible_retained' AND BINARY r.cohort_receipt_sha256=BINARY c.receipt_sha256 AND r.unknown_group_count=0 AND r.unknown_source_count=0 AND BINARY u.catalog_receipt_sha256=BINARY r.receipt_sha256 AND d.database_purge_generation=j.database_purge_generation AND BINARY policy.active_policy_sha256=BINARY j.policy_sha256 AND BINARY policy.active_policy_version=BINARY p.policy_version AND BINARY runtime.runtime_epoch_sha256=BINARY JSON_UNQUOTE(JSON_EXTRACT(c.receipt_json,'$.profile.primaryBinding.runtimeEpochSha256')) AND (SELECT COUNT(*) FROM tenant_telemetry_retained_source_canonical_entries e WHERE BINARY e.request_id=BINARY j.request_id)=u.entry_count AND NOT EXISTS (SELECT 1 FROM tenant_telemetry_retained_source_canonical_entries e WHERE BINARY e.request_id=BINARY j.request_id AND (e.completed_claim_attempt<>j.attempts OR BINARY e.completed_claim_token_sha256<>BINARY SHA2(CONCAT('["tenant-database-purge-claim-token-v1",',JSON_QUOTE(j.claim_token),']'),256))) AND NOT EXISTS (SELECT 1 FROM legal_holds h WHERE BINARY h.tenant_id=BINARY OLD.tenant_id AND h.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM legal_hold_controls h WHERE BINARY h.tenant_id=BINARY OLD.tenant_id AND h.active_hold_count<>0 FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences f WHERE BINARY f.tenant_id=BINARY OLD.tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_replay_runs run WHERE run.phase IN ('prepared','replay_sealed') FOR SHARE) FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='tenant parent deletion lacks retained-source pre-delete bridge'; END IF; END IF; END;

-- Independent bottom-up roots. 136 bytes per SHA-pair bounds GROUP_CONCAT before
-- evaluation; use the lesser of the actual session budget and a fixed 1MiB ceiling.
